export function resolveLanguage(saved, browserLanguage) {
  if (saved === 'en' || saved === 'th') return saved;
  return browserLanguage?.toLowerCase().startsWith('th') ? 'th' : 'en';
}

export function toggleLanguage(current) {
  return current === 'th' ? 'en' : 'th';
}

export function translateText(source, language) {
  if (language !== 'th' || !source) return source;
  const key = source.trim().replace(/\s+/gu, ' ');
  const translated = thai[key];
  if (!translated) return source;
  return source.replace(source.trim(), translated);
}

export function hasThaiTranslation(source) {
  return Object.hasOwn(thai, source.trim().replace(/\s+/gu, ' '));
}
